ALTER POLICY "Read addenda of a readable note" ON public.encounter_addenda USING (EXISTS (SELECT 1 FROM public.encounters e WHERE e.id = encounter_addenda.encounter_id AND (e.clinician_user_id = auth.uid() OR public.clinician_has_patient_access(e.patient_user_id) OR public.is_assigned_to_patient(auth.uid(), e.patient_user_id) OR public.practice_has_clinical_access(e.patient_user_id))));
ALTER POLICY "Read goals of a readable plan" ON public.fhir_care_goals USING (EXISTS (SELECT 1 FROM public.fhir_care_plans p WHERE p.id = fhir_care_goals.care_plan_id AND ((p.patient_user_id = auth.uid() AND p.status <> 'draft') OR public.clinician_has_patient_access(p.patient_user_id) OR public.institution_has_clinical_access(p.patient_user_id))));
ALTER POLICY "Read line items of a readable invoice" ON public.fhir_invoice_items USING (EXISTS (SELECT 1 FROM public.fhir_invoices i WHERE i.id = fhir_invoice_items.invoice_id AND ((i.patient_user_id = auth.uid() AND i.status <> 'draft') OR public.clinician_has_patient_access(i.patient_user_id) OR public.institution_has_patient_access(i.patient_user_id))));